import json,pathlib
R=pathlib.Path('.')
def write(b,slug,name,identity,anatomy,moment,power,camera,light,surface,setting,req,choices,variant,aura):
 claims=list(dict.fromkeys(c for k,t,cs in req for c in cs));d=dict(slug=slug,name=name,batch=b,depicted_variant=variant,basis_claim_ids=claims,visual_requirements=[dict(kind=k,description=t,claim_ids=cs) for k,t,cs in req],aura=aura,artistic_choices=choices)
 d['prompt']=f'ONE original square premium painterly cinematic Mitoloka illustration of {name}, {identity}.\nANATOMY: {anatomy}\nMOMENT: {moment}\nPOWER: {power}\nSCALE & CAMERA: extreme low angle; {camera}\nLIGHT & WEATHER: {light}\nSURFACE: {surface}\nSETTING: {setting}\nMOOD: dangerous, imposing or awe-inspiring, never cute, calm or decorative.\nHARD CONSTRAINTS: no text, pseudoinscriptions, lettering, logo, border, frame or watermark; no extra heads, limbs or fingers; no borrowed film, game, anime or comic design; no nudity or explicit gore; no generic glowing aura, neon outline, energy ribbons, floating runes. Strong painterly brushwork, not plastic 3D.'
 p=R/f'data/artwork-generated/batch-{b}/drafts/resume100-A/{slug}-spec.json';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
def C(s,*n):return [f'{s}-c{x:02}' for x in n]
s='yamaoroshi';write(1967,s,'Yamaoroshi','the neglected metal grater become a spiny humanoid yokai', 'one humanoid body, one unmistakable elongated METAL GRATER HEAD whose entire front and sides carry many dull bent grating spikes, two dark eyes and one mouth set in that grater head, two humanlike arms with five fingers per hand and two legs; faded opaque brown work robe; NOT an ordinary porcupine, NOT a human wearing a mask [c02,c05,c08]', 'Crawl forward over abandoned kitchen floor toward the viewer, thrust its enormous-in-perspective rusty grater face close to the lens, bracing one hand on the boards while the other reaches forward; grimace, not smiling', 'no documented traditional power; physical menace through metal grater anatomy and intrusive crawl only. No wind magic, no supernatural particles', 'normal utensil/yokai scale kept ambiguous, extreme close framing, grater face fills upper two thirds and spikes silhouette clearly at thumbnail size; no human scale comparison', 'one dominant old hearth fire offscreen, amber rim light, deep walnut shadows and ordinary floating kitchen dust', 'dull rusty grater teeth, oxidized metal, weathered fabric, splintered wood', 'the kitchen tools of its documented illustration: daikon radish, shell ladle, mortar tucked into dark floor edges [c09]', [('anatomy','Humanoid with grater head and many dull spikes',C(s,2,5,8)),('setting','Kitchen tools: daikon, shell ladle, mortar',C(s,9))], ['Choose traditional grater humanoid, omit Heisei wind interpretation c10.','Opaque brown robe and low close crawl are editorial; no added giant size or magical effects.'], 'Humanoid living neglected grater, no wind-power interpretation.', 'Dull grater spikes c02/c05/c08 confront viewer in close crawl; no invented effects.')
s='adaro-mythology';write(1967,s,'Adaro','a malevolent partly human partly fish sea spirit of Makira, specifically the adaro ni matawa variant', 'one adult male half-human half-fish sea spirit, ONE head, two natural eyes, two arms and hands with five fingers each; lower body one powerful scaled fish tail with a single forked tail fin, no human legs; human torso entirely covered by opaque dark woven vest; no horns, shark head, wings, face gills or extra fins invented [c09]', 'Surge half out of a breaking sea wave toward viewer and cast three real flying fish forward like darts with one arm, other hand braces water; eyes confront viewer', 'adaro ni matawa attacks men with flying fish [c10]; three silver flying fish with their real winglike pectoral fins streak physically through air from its throwing gesture, no beams, no magic glow, no guns', 'tight water-level low-angle foreground, spirit head and arms dominate with fish tail visibly curling along lower edge; normal human torso scale, no tiny ship comparison', 'one dominant moon, hard silver rim light, deep walnut shadows, violent natural sea spray', 'salt-wet dark human skin, coarse woven vest, tactile bronze-black fish scales, living silver flying fish', 'far out at sea near a small Makira coastal island, dark island silhouette far behind [c09]', [('anatomy','Partly human partly fish sea spirit, not ghost shark variant',C(s,9)),('effect','Malevolent sea spirit shoots men with flying fish',C(s,10)),('setting','Open sea or coastal islands',C(s,9))], ['Select only sea-spirit c09/c10 class; do not combine ghost-shark c03/c08 anatomy.','Opaque woven vest, normal humanoid proportions and single fish tail are restrained editorial realization of partly human/fish form.','Three flying fish used as physical projectiles; no invented energy.'], 'Adaro ni matawa sea spirit, partly human and fish, attacking with flying fish.', 'Physical flying-fish attack c10 and half-fish body c09 provide menace; no glow.')
s='agunua';write(1967,s,'Agunua','the male cosmic winged serpent and sea deity of Makira, respectfully awe-inspiring', 'ONE immense living male serpent, one snake head, two eyes, one long limbless coiling snake body and tail, TWO large feathered wings as restrained bilateral rendering of documented winged serpent; no human arms, legs, extra heads, horns or four-eyed design [c01,c06,c08]', 'Rise from the storm sea toward the low viewer, uncoil the vast serpent body and open both wings while a storm breaks behind its head; solemn focused snake face, mouth closed, never a vicious demon', 'sea deity c03 and creator of thunder, lightning, rain and storms c07: a single natural lightning fork strikes the distant sea behind it, wind pushes rain and real ocean waves rise and break against its coiling body. No magic beams or rays emitted from body', 'cosmic serpent fills square frame, head upper central foreground, long snake coils and both wings clearly visible; no human worshippers needed', 'one dominant lightning flash behind the serpent, warm gold-edged storm light, deep brown shadows, slanting rain and heavy sea spray', 'wet dark bronze snake scales, weathered ivory-gold flight feathers, white wave foam', 'sea off Makira, storm horizon [c03,c07,c11]', [('anatomy','Male cosmic winged serpent deity',C(s,1,6,8)),('effect','Sea domain and creator of thunder/lightning/rain/storms',C(s,3,7)),('setting','Sea off Makira',C(s,3,11))], ['Respectful cosmic majesty, never demonize living Melanesian deity.','Two feathered wings are editorial rendition of winged serpent c06; no borrowed Hatuibwari four-eye/limb iconography not present in this entry.','Natural sea and storm act physically, no body glow.'], 'Male cosmic winged serpent Agunua, sea-and-storm scene.', 'Cosmic serpent c01/c06/c08 rises over sea c03 under its created storms c07.')
s='akurojin-no-hi';write(1967,s,'Akurojin-no-hi','the moving ghostly fire of rainy nights at an Ise river crossing', 'a SINGLE disembodied natural-looking ghostly FLAME, no face, eyes, limbs, human figure, lantern casing, horns or invented animal body; intensely textured amber flame and dark smoke, compact flame shaped like a carried lantern light, never a giant fire monster [c01,c05]', 'Pass directly in front of the very low camera along the log river crossing, turbulent flame leaning sideways mid-flight and briefly filling foreground as it moves back and forth; an adult traveller lies face-down safely on distant bridge planks waiting for the fire to pass [c05,c06]', 'documented moving ghostly fire [c01,c05], natural firelight on wet wood and river ripples only. Serious illness c07 is NOT visualized; no infection rays or burning bridge, no firestorm', 'extreme close-up of passing flame, occupies at least two thirds of square frame; log bridge perspective recedes behind; flame compact lanternlike size, no giant scale', 'the ghostly flame itself is the ONE dominant amber light, rim lighting raindrops, black rainy night; realistic smoke and falling rain', 'layered turbulent translucent fire, rain beads, soaked rough timber, moving deep river water', 'rainy night at deep river with a simple log bridge in Ise, Japan [c03,c04,c09]', [('anatomy','Disembodied ghostly fire, no invented body',C(s,1,5)),('effect','Moves back and forth like carried lantern light; traveller drops to ground',C(s,5,6)),('setting','Rainy night, deep river and log bridge in Ise',C(s,3,4,9))], ['No bodily anatomy invented; documented active flame is the entire subject.','Extreme proximity keeps compact lantern-sized fire dominant, not enlarged into giant firestorm.','Distant fully clothed prone traveller follows c06; serious illness is not rendered as invented rays.'], 'Active disembodied ghostly flame crossing a rain-soaked log bridge.', 'Moving ghostly fire c05 confronts viewer; prone traveller follows c06, no invented sickness effect.')
s='andromalius';write(1977,s,'Andromalius','the formidable Goetic earl who appears as a man holding a large serpent and recovers thieves and stolen goods', 'one adult male in fully opaque weathered dark medieval mantle and tunic, ONE human head, two eyes, two arms and two legs, human face without horns or fangs; his right hand holds ONE LARGE living SERPENT firmly behind its head, serpent body coils across his forearm then descends visibly; serpent one head and two eyes, no wings or legs [c03,c05]', 'Stride directly toward viewer, thrust the large serpent toward camera in his right hand while his left hand drags a terrified fully clothed thief back by the wrist; thief clutches a torn sack spilling a few stolen silver cups onto stone [c04,c05]', 'Recover thief and stolen goods [c04,c05], punishment implied by the forceful return only. No magical beams, no levitating objects, no supernatural glowing eyes, no invented spirit army', 'extreme low close angle, Andromalius and coiled large serpent occupy 85 percent of image; thief lower and behind but normal human proportions, earl NOT a giant', 'one torch outside frame casts dominant amber sidelight, hard rim light on snake scales and mantle, deep walnut shadows, airborne stone dust', 'weathered opaque wool, scarred ordinary human skin, leathery serpent scales, tarnished stolen cups', 'a dark unlabelled stone passage, neutral editorial staging for return of thief and goods; no invented ritual circle or inscriptions', [('anatomy','Man holding large serpent',C(s,3,5)),('effect','Brings back thief and stolen goods; punishment',C(s,4,5,6))], ['Human form and serpent attribute kept exact; no horns, fangs or giant body.','Stone passage, dark mantle, returning thief action and tarnished cups are editorial staging of documented recovery.','Menace through looming close camera, serpent and forceful act; no invented visible magic.'], 'Goetic human earl holding a large serpent, returning a thief and stolen goods.', 'Serpent attribute c03/c05 and active return of thief and goods c04/c05 create threat.')
s='aonyobo';write(1977,s,'Aonyobo','the uncanny blue-skinned court-woman yokai in a ruined noble residence', 'ONE adult female humanoid yokai, one head and two eyes, TWO arms and two legs under many fully opaque layered ancient Japanese court kimono, tattered and moth-eaten but body always covered; visibly deep BLUE skin at neck, hands and ears; thick chalk WHITE face makeup with VERY HIGH painted eyebrows and visibly BLACKENED normal human teeth; elaborate old court hair, no horns, fangs or claws [c02,c03]', 'Whip her head around from fixing her hair toward the intruding viewer, lean abruptly close, mouth partly open displaying blackened teeth, one blue hand still lifting a plain unlettered comb beside hair, other blue hand grips frayed robe; fixed accusing stare, no smile [c04]', 'no documented visible magic; uncanny appearance, abrupt motion and abandoned dwelling alone create menace. No glowing eyes, spectral mist, levitation, poverty rays or invented curse effects', 'tight very low three-quarter face close-up, white face and black teeth dominate upper square, blue hands and neck plainly visible even at thumbnail; normal human height, no giant scale', 'one dominant old oil lamp low to one side offscreen, warm amber rim light, deepest walnut shadows, thin ordinary dust in room', 'cracked chalk cosmetic over blue skin, ink-black teeth, dry coarse ancient brocade and moth holes, fraying kimono layers, dusty hair', 'abandoned former noble house inside a ruined bamboo grove, broken wooden wall reveals dark bamboo at edge [c04,c05]', [('anatomy','Blue-skinned court woman; layered tattered kimono, white makeup, high painted brows and black teeth',C(s,2,3)),('setting','Ruined noble house within abandoned bamboo grove, fixes her hair',C(s,4,5))], ['No documented power: uncanny blue skin, black teeth and abruptly confronting viewer supply menace.','Oil lamp, plain comb, exact close framing and abrupt head turn are editorial action from grooming account c04.','Opaque many-layered kimono; no giant body, horns, claws or demonic additions.'], 'Blue court-woman spirit with white makeup and black teeth, turning during grooming.', 'Blue skin c02, white makeup/high brows/black teeth c03 and sudden grooming interruption c04 create uncanny confrontation.')
